def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version_part, _ = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (everything after '-')
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
            prerelease_ids = prerelease.split('.')
        else:
            core = version_part
            prerelease_ids = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, prerelease_ids)

    def compare_prerelease(pre1, pre2):
        # If both None, they're equal (same version without pre-release)
        if pre1 is None and pre2 is None:
            return 0

        # Version without pre-release sorts after version with pre-release
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric: compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_digit1:
                # id1 is digit, id2 is not: digit sorts first
                return -1
            elif is_digit2:
                # id2 is digit, id1 is not: digit sorts first
                return 1
            else:
                # Both non-numeric: compare ASCII
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    def sort_key(version):
        major, minor, patch, prerelease_ids = parse_version(version)
        return (major, minor, patch, prerelease_ids is not None, prerelease_ids or [])

    # Use stable sort with custom comparison
    indexed_versions = [(i, version) for i, version in enumerate(versions)]

    def compare_two(item1, item2):
        idx1, v1 = item1
        idx2, v2 = item2

        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        # Compare MAJOR.MINOR.PATCH
        if parsed1[:3] != parsed2[:3]:
            return -1 if parsed1[:3] < parsed2[:3] else 1

        # Compare pre-release
        cmp_pre = compare_prerelease(parsed1[3], parsed2[3])
        if cmp_pre != 0:
            return cmp_pre

        # Equal precedence: keep input order
        return -1 if idx1 < idx2 else (1 if idx1 > idx2 else 0)

    from functools import cmp_to_key
    sorted_indexed = sorted(indexed_versions, key=cmp_to_key(compare_two))

    return [version for _, version in sorted_indexed]

